mapper.select:
SELECT 


    m.store_id = #{q.storeId}
    AND m.platform = #{q.platform}
    AND m.marketplace = #{q.marketplace}
    AND m.monitor_type = #{q.monitorType}
    AND m.status = #{q.status}

        AND (m.item_id LIKE CONCAT('%', #{q.keyword}, '%') OR m.title LIKE CONCAT('%', #{q.keyword}, '%')
             OR m.brand LIKE CONCAT('%', #{q.keyword}, '%') OR m.seller_sku LIKE CONCAT('%', #{q.keyword}, '%'))


        AND EXISTS (SELECT 1 FROM ecom_monitor_alert a WHERE a.monitor_id = m.id AND a.status = 'NEW')



ORDER BY COALESCE(m.benchmark_id, m.id) DESC, CASE WHEN m.benchmark_id IS NULL THEN 0 ELSE 1 END, m.id
